import AccessibilitySettingsModal from 'theme_moove/accessibilitysettings_modal';

const openModal = async() => {
  const modal = await AccessibilitySettingsModal.create({});
  modal.show();
};

return {
  init: () => {
    const settingsButton = document.querySelector('#accessibilitysettings-control');
    if (settingsButton) {
      settingsButton.addEventListener('click', (e) => {
        e.preventDefault();
        openModal();
      });
    }
  }
};
